import { test, expect } from '@playwright/test';

test.describe('Login Page Mobile Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display login form correctly on mobile devices', async ({ page }) => {
    // Set viewport to mobile width
    await page.setViewportSize({ width: 375, height: 812 });

    // Verify login form is visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Verify email input field is visible and accessible
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();

    // Verify password input field is visible and accessible
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();

    // Verify login button is visible and accessible
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();

    // Verify error messages are visible and accessible
    const errorMessage = page.getByText('Email address is required');
    await expect(errorMessage).toBeVisible();

    // Verify success message is not visible
    const successMessage = page.getByText('Login successful');
    await expect(successMessage).not.toBeVisible();

    // Verify form is responsive and does not overflow
    await expect(page).toHaveViewportSize({ width: 375, height: 812 });
    await expect(page).toHaveViewportSize({ width: 375, height: 812 });
  });

  test('should handle login on mobile with valid credentials', async ({ page }) => {
    // Set viewport to mobile width
    await page.setViewportSize({ width: 375, height: 812 });

    // Fill email input with valid value
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    // Fill password input with valid value
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('password123');

    // Click login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Login successful');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    const dashboard = page.getByRole('main');
    await expect(dashboard).toBeVisible();

    // Verify error messages are not visible
    const errorMessage = page.getByText('Email address is required');
    await expect(errorMessage).not.toBeVisible();

    // Verify login button is disabled
    await expect(loginButton).toBeDisabled();
  });
});
